// pkinative — runtime smoke checks
// ================================
// One parse, one verify per signature family and one PKCS#12 round trip,
// run against the BUILT package (dist/index.js) on a runtime other than
// Node: Deno, Bun and headless Chromium (.github/workflows/ci.yml, job
// `runtimes`). README.md and the landing page say the same build runs
// there; this is what holds that sentence to a run instead of a belief.
//
// Plain ESM with no import of its own and no host API beyond what every
// target exposes — `globalThis.crypto.subtle`, `atob`, `TextEncoder` — so the
// one file runs unchanged in all of them. The fixtures are inlined:
//   X1  tests/fixtures/certs/isrg-root-x1.der (RSA 4096, sha256WithRSAEncryption)
//   X2  tests/fixtures/certs/isrg-root-x2.der (P-384, ecdsa-with-SHA384)
//   P12 a P-256 key and its self-signed certificate written by OpenSSL 3.5.5:
//       `openssl pkcs12 -export -pbmac1_pbkdf2 -passout pass:smoke` — PBES2,
//       PBKDF2-HMAC-SHA256, AES-256-CBC, integrity by PBMAC1 (RFC 9579).
//   ED448_ROOT, ED448_P7S  an Ed25519 root and a CMS SignedData whose one
//       signer holds an Ed448 key under a certificate that root issued,
//       digesting with SHAKE256 (RFC 8419 §3.1); the content is attached.
//       Written once by node:crypto and pkinative's own builders, because
//       a runtime without Ed448 cannot make the key, and the check's point
//       is what each runtime answers for it (ADR 0022).
// The Ed25519 key of the Ed25519 check is generated by the runtime itself:
// the smoke harness may call generateKey, the library never does.

const X1 ='';
const X2 = '';
const P12 = '';
const P12_PASSWORD = 'smoke';
const ED448_ROOT = '';
const ED448_P7S = '';

/**
 * What each runtime answers for the Ed448 CMS signer (ADR 0022): the digest
 * is pkinative's SHAKE256 everywhere, the signature is the host's Ed448 —
 * which Node has, Bun and Chromium do not, and Deno may or may not. A host
 * that changes its answer fails this check, so the expectation is named here
 * rather than discovered.
 *
 * @returns {'verified' | 'unsupported' | 'either'}
 */
function ed448Expectation() {
    if (typeof Deno !== 'undefined') return 'either';
    if (typeof Bun !== 'undefined') return 'unsupported';
    if (typeof navigator !== 'undefined' && /Chrom(?:e|ium)\//.test(navigator.userAgent)) return 'unsupported';
    return 'verified';
}

/** @param {string} b64 */
function bytes(b64) {
    const bin = atob(b64);
    const out = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
    return out;
}

/** @param {unknown} ok @param {string} what */
function check(ok, what) {
    if (ok !== true) throw new Error(`runtime smoke: ${what}`);
}

/**
 * Run every check against the module namespace of dist/index.js.
 *
 * @param {Record<string, any>} m the pkinative module namespace
 * @returns {Promise<string[]>} one line per passed check; throws on the first failure
 */
export async function runChecks(m) {
    const passed = [];
    const quiet = { onDiagnostic: () => undefined };

    const x1 = m.parseCertificate(bytes(X1), quiet);
    check(m.formatDistinguishedName(x1.subject) === 'CN=ISRG Root X1,O=Internet Security Research Group,C=US', 'X1 subject');
    check(await m.verifySelfSignature(x1), 'X1 RSASSA-PKCS1-v1_5 self-signature');
    passed.push('parse + verify RSASSA-PKCS1-v1_5 (ISRG Root X1)');

    const x2 = m.parseCertificate(bytes(X2), quiet);
    check(await m.verifySelfSignature(x2), 'X2 ECDSA P-384 self-signature');
    passed.push('parse + verify ECDSA P-384, DER to P1363 (ISRG Root X2)');

    const fingerprint = await m.computeFingerprintAsync(x1.der, 'SHA-256');
    const hex = Array.from(fingerprint, (b) => b.toString(16).padStart(2, '0')).join('');
    check(hex === '96bcec06264976f37460779acf28c5a7cfe8a3c0aae11a8ffcee05c0bddf08c6', 'X1 SHA-256 fingerprint');
    passed.push('SHA-256 fingerprint through Web Crypto');

    const opened = await m.openPkcs12(bytes(P12), { password: P12_PASSWORD });
    check(opened.valid && opened.integrity === 'verified', `PKCS#12 open (${opened.reasons.map((r) => r.code).join(', ')})`);
    const key = opened.keys[0];
    check(key !== undefined && key.signingKey !== undefined && key.certificate !== undefined, 'PKCS#12 key and certificate');
    const issued = await m.createCertificate({
        serialNumber: 2n,
        issuerDer: key.certificate.subject.der,
        subject: [[{ type: '2.5.4.3', value: 'pkinative runtime smoke leaf' }]],
        notBefore: Date.UTC(2026, 0, 1),
        notAfter: Date.UTC(2027, 0, 1),
        subjectPublicKey: key.certificate.subjectPublicKeyInfo.der,
    }, key.signingKey);
    check(await m.verifyCertificateSignature(m.parseCertificate(issued, quiet), key.certificate), 'certificate signed by the PKCS#12 key');
    passed.push('PKCS#12 open (PBMAC1, PBES2/AES-256-CBC) + ECDSA P-256 sign + verify');

    const pair = await crypto.subtle.generateKey({ name: 'Ed25519' }, false, ['sign', 'verify']);
    const spki = new Uint8Array(await crypto.subtle.exportKey('spki', pair.publicKey));
    const name = [[{ type: '2.5.4.3', value: 'pkinative runtime smoke Ed25519' }]];
    const self = await m.createCertificate({
        serialNumber: 3n, issuer: name, subject: name,
        notBefore: Date.UTC(2026, 0, 1), notAfter: Date.UTC(2027, 0, 1),
        subjectPublicKey: spki,
    }, { key: pair.privateKey, algorithm: { name: 'Ed25519' } });
    check(await m.verifySelfSignature(m.parseCertificate(self, quiet)), 'Ed25519 self-signature');
    passed.push('Ed25519 build + sign + verify');

    const ed448 = await m.verifySignedData({ signedData: bytes(ED448_P7S), trustAnchors: [m.parseCertificate(bytes(ED448_ROOT), quiet)], at: Date.UTC(2026, 5, 1) });
    const notChecked = ed448.reasons.length === 1 && ed448.reasons[0].code === 'PKI_REASON_SIGNATURE_NOT_CHECKED' && ed448.reasons[0].errorCode === 'PKI_CRYPTO_KEY_UNSUPPORTED';
    const outcome = ed448.valid ? 'verified' : notChecked ? 'unsupported' : `other: ${ed448.reasons.map((r) => `${r.code}${r.errorCode === undefined ? '' : `/${r.errorCode}`}`).join(', ')}`;
    const expected = ed448Expectation();
    check(expected === 'either' ? !outcome.startsWith('other') : outcome === expected, `Ed448 CMS signer: expected ${expected}, got ${outcome}`);
    passed.push(`Ed448 CMS signer (SHAKE256 digest, RFC 8419): ${outcome === 'verified' ? 'verified — this host has Ed448' : 'SIGNATURE_NOT_CHECKED / PKI_CRYPTO_KEY_UNSUPPORTED — this host has no Ed448'}${expected === 'either' ? ' (either accepted here)' : ''}`);

    return passed;
}
